// checkUsable verifies that the request is still usable.
// Returns true if the request can be used, false otherwise.
func (r *Request) checkUsable(opChain *chain, where string) bool {
	if r.expectCalled {
		opChain.fail(AssertionFailure{
			Type: AssertUsage,
			Errors: []error{
				fmt.Errorf(
					"unexpected %s call after Expect()", where),
			},
		})
		return false
	}
	return true
}

