cat > /tmp/expect_patch.txt << 'EOF'
// Expect constructs http.Request, sends it, receives http.Response, and
// returns a new Response instance.
//
// Request is sent using Client interface, or WebsocketDialer in case of
// WebSocket request.
//
// After calling this method, any further calls to WithXXX() methods will
// fail with AssertUsage error. It is not allowed to call this method more
// than once.
//
// Example:
//
//	req := NewRequestC(config, "PUT", "http://example.com/path")
//	req.WithJSON(map[string]interface{}{"foo": 123})
//	resp := req.Expect()
//	resp.Status(http.StatusOK)
func (r *Request) Expect() *Response {
	opChain := r.chain.enter("Expect()")
	defer opChain.leave()

	if r.expectCalled {
		opChain.fail(AssertionFailure{
			Type: AssertUsage,
			Errors: []error{
				errors.New(
					"unexpected Expect() call after previous Expect()"),
			},
		})
		return newResponse(responseOpts{
			config: r.config,
			chain:  opChain,
		})
	}

	r.expectCalled = true

	resp := r.roundTrip(opChain)
