package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"

	"github.com/gavv/httpexpect/v2"
)

type simpleReporter struct{}

func (r *simpleReporter) Errorf(format string, args ...interface{}) {
	fmt.Printf("ERROR: "+format+"\n", args...)
}

func (r *simpleReporter) Fatalf(format string, args ...interface{}) {
	fmt.Printf("FATAL: "+format+"\n", args...)
	os.Exit(1)
}

func main() {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()

	config := httpexpect.Config{
		BaseURL:  server.URL,
		Reporter: &simpleReporter{},
	}

	// Test 1: Request - Calling WithXXX after Expect should fail
	fmt.Println("Test 1: Request - Calling WithHeader after Expect")
	req := httpexpect.NewRequestC(config, "GET", "/path")
	resp := req.Expect()
	_ = resp

	req.WithHeader("X-Test", "value")
	fmt.Println("  ^ Should have reported an AssertUsage error above")

	// Test 2: Request - Calling Expect twice should fail
	fmt.Println("\nTest 2: Request - Calling Expect twice")
	req2 := httpexpect.NewRequestC(config, "GET", "/path2")
	resp1 := req2.Expect()
	_ = resp1

	resp2 := req2.Expect()
	_ = resp2
	fmt.Println("  ^ Should have reported an AssertUsage error above")

	fmt.Println("\nAll tests completed!")
}
EOF
